// wf.listing.trust > "Plan" (platform P12, D-112): the job app.job_start claimed, or nothing when another run
// already has it (the job is then not queued any more and the row is empty).
const row = $input.first().json || {};
if (!row.job_id) return [{ json: { none: true } }];
const input = row.input || {};
return [{ json: { none: false, job_id: row.job_id, attempts: row.attempts, max_attempts: row.max_attempts,
  listing_id: input.listing_id, user_id: input.user_id, request_id: row.job_id } }];

// the listing to check; the job id is the request id of the trace
const p = $('Plan').first().json;
return [{ json: { listing_id: p.listing_id, request_id: p.job_id } }];

// wf.listing.trust > "Report": the stored report for the second app.listing_submit call, as in the v1 submit.
// A check that stored no report gives report_id null: app.listing_submit then answers 409 {trust: missing}.
const t = $input.first().json || {};
const p = $('Plan').first().json;
return [{ json: { params: [p.user_id, p.listing_id, JSON.stringify(t.ok ? { report_id: t.report_id } : { report_id: null })] } }];

// wf.listing.trust > "Next steps": app.listing_submit's answer; a newly published listing is embedded at once for
// the search by meaning (as in the v1 submit; a failed embedding leaves it to the embed job, D-083).
const r = ($input.first().json || {}).r || null;
const cfg = (r && r.embed) || {};
const embed = !!(r && r.status === 200 && r.embed_text);
return [{ json: { r, embed, model: cfg['ollama.embed_model'] || 'bge-m3',
  embed_url: `${String(cfg['ollama.base_url'] || '').replace(/\/+$/, '')}/api/embed`,
  embed_body: { model: cfg['ollama.embed_model'] || 'bge-m3', input: [(r && r.embed_text) || ''], truncate: true,
                keep_alive: cfg['llm.keep_alive'] || '10m' } } }];

// wf.listing.trust > "Embedding rows": Ollama answer -> rows for app.store_listing_embeddings.
const n = $('Next steps').first().json;
const res = $input.first().json || {};
let b = res.body !== undefined ? res.body : res;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
const v = (b && b.embeddings && b.embeddings[0]) || null;
if (!Array.isArray(v) || v.length !== 1024) return [{ json: { skip: true } }];
return [{ json: { skip: false, params: [n.model, JSON.stringify([{ id: n.r.data.listing_id, v: `[${v.join(',')}]` }])] } }];

// wf.listing.trust > "Finish input": the job's output (docs/openapi.yaml, POST /v2/listings/{id}/submit) and the
// Trust agent's steps for the trace (request id = the job id). outcome: published, in_review, rejected, or
// not_submitted when the listing no longer passes the checks. No stored report: a transient failure, retried once
// by wf.jobs.dispatch; then the job fails with trust_check_failed and the listing stays a draft.
const p = $('Plan').first().json;
const n = $('Next steps').first().json;
const r = n.r || {};
let steps = [];
try { steps = ($('Trust check').first().json || {}).steps || []; } catch (e) { steps = []; }
const last = $input.first().json || {};
const exec = String($execution.id || '');
const finish = (status, output, error, transient) => [{ json: { params: [p.job_id, status, JSON.stringify(output), error, transient,
  'wf.listing.trust', exec, JSON.stringify(steps)] } }];
const base = { listing_id: p.listing_id, listing: null, signals: [], error: null };
if (r.status === 200 && r.data) {
  const embedded = n.embed ? last.stored !== undefined && last.stored !== null && !last.error : null;
  return finish('succeeded', { ...base, outcome: 'published',
    listing: { ...r.data, warnings: embedded === false ? ['embedding_pending'] : [] } }, null, false);
}
const d = ((r.error || {}).details || [])[0] || {};
if (d.field === 'trust' && (d.issue === 'in_review' || d.issue === 'rejected')) {
  return finish('succeeded', { ...base, outcome: d.issue, signals: d.signals || [] }, null, false);
}
if (d.field === 'trust' && d.issue === 'missing') {
  return finish('failed', { ...base, outcome: null }, 'trust_check_failed', true);
}
if (r.error) {
  return finish('succeeded', { ...base, outcome: 'not_submitted',
    error: { code: r.error.code, details: r.error.details || [] } }, null, false);
}
return finish('failed', { ...base, outcome: null }, 'no_result', true);
